    if not alive_opponents:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    effective_threat = cindy_bid if cindy_bid is not None else highest_prev

    tight_supply = supply <= 18
    medium_supply = supply <= 21
    critical = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    bid = 0.0

    if critical:
        if effective_threat >= 90:
            bid = min(budget, effective_threat + 2.0)
        elif effective_threat > 0:
            bid = min(budget, max(60.0, effective_threat + 2.0))
        else:
            bid = min(budget, 65.0)
    elif tight_supply:
        if effective_threat >= 90:
            bid = min(budget, effective_threat + 1.0)
        elif effective_threat >= 50:
            bid = min(budget, effective_threat + 2.0)
        else:
            bid = min(budget, 58.0)
    elif medium_supply:
        if pressured:
            if effective_threat >= 90:
                bid = min(budget, effective_threat + 1.0)
            elif effective_threat > 0:
                bid = min(budget, max(48.0, effective_threat + 1.5))
            else:
                bid = min(budget, 45.0)
        else:
            bid = min(budget, 18.0)
    else:
        if pressured and effective_threat > 0 and effective_threat < 80:
            bid = min(budget, max(35.0, effective_threat + 1.0))
        else:
            bid = min(budget, 8.0)

    if budget <= 0:
        return 0.0

    if hp >= 7 and no_water_days == 0 and not tight_supply and effective_threat >= 90:
        bid = min(budget, 5.0)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents only
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    # If no one else is alive, conserve
    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids to infer pressure
    prev_bids = []
    for o in alive:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base bid: tie/beat their typical aggression without burning budget
    # If they already bid near my salary, increase; otherwise match mid-high.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * 0.72
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * 0.50

    # Supply pressure: lower supply -> higher bids to avoid no-water days
    # supply in [15,25]
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)  # 0..1
    # When supply is low (norm near 0), add pressure
    supply_multiplier = 1.12 - 0.25 * supply_norm

    # My hp urgency
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])
    if hp <= 1.5 or no_water_days >= 2:
        urgency = 1.25
    elif hp <= 3.0 or no_water_days == 1:
        urgency = 1.10
    else:
        urgency = 1.00

    bid = base * supply_multiplier * urgency

    # Ensure we never bid more than our budget
    bid = float(min(my_status['budget'], bid))

    # If budget is tiny, still bid something to avoid total starvation
    if bid <= 0.0:
        return 0.0

    # Small strategic floor to compete against typical bids (Alex/Cindy ~80-95)
    # but remain within budget.
    competitor_floor = 75.0
    if bid < competitor_floor and my_status['budget'] >= competitor_floor:
        bid = competitor_floor

    return float(bid)

